-- Module Identity : sessions (refresh tokens rotatifs), réinitialisation de mot
-- de passe et défis OTP. Aucun secret en clair : seuls des HMAC-SHA256
-- hexadécimaux (64 caractères) sont stockés.

-- CreateEnum
CREATE TYPE "otp_channel" AS ENUM ('SMS', 'EMAIL');

-- CreateEnum
CREATE TYPE "otp_purpose" AS ENUM ('PHONE_VERIFICATION', 'EMAIL_VERIFICATION', 'LOGIN', 'PASSWORD_RESET', 'PHONE_CHANGE');

-- CreateTable
CREATE TABLE "auth_sessions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "public_id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "user_id" BIGINT NOT NULL,
    "family_id" UUID NOT NULL,
    "token_hash" CHAR(64) NOT NULL,
    "device_id" VARCHAR(128),
    "device_name" VARCHAR(150),
    "ip_address" INET,
    "user_agent" VARCHAR(512),
    "last_used_at" TIMESTAMPTZ(6),
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "revoked_at" TIMESTAMPTZ(6),
    "revoked_reason" VARCHAR(32),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "auth_sessions_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "auth_sessions_token_hash_hex_chk" CHECK ("token_hash" ~ '^[0-9a-f]{64}$'),
    CONSTRAINT "auth_sessions_expiry_chk" CHECK ("expires_at" > "created_at"),
    CONSTRAINT "auth_sessions_revocation_chk" CHECK (("revoked_at" IS NULL) = ("revoked_reason" IS NULL))
);

-- CreateTable
CREATE TABLE "password_reset_tokens" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "user_id" BIGINT NOT NULL,
    "token_hash" CHAR(64) NOT NULL,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "used_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "password_reset_tokens_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "password_reset_tokens_token_hash_hex_chk" CHECK ("token_hash" ~ '^[0-9a-f]{64}$'),
    CONSTRAINT "password_reset_tokens_expiry_chk" CHECK ("expires_at" > "created_at")
);

-- CreateTable
CREATE TABLE "otp_challenges" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "public_id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "user_id" BIGINT,
    "channel" "otp_channel" NOT NULL,
    "purpose" "otp_purpose" NOT NULL,
    "destination_hash" CHAR(64) NOT NULL,
    "code_hash" CHAR(64) NOT NULL,
    "attempts" SMALLINT NOT NULL DEFAULT 0,
    "max_attempts" SMALLINT NOT NULL,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "consumed_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "otp_challenges_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "otp_challenges_hashes_hex_chk" CHECK ("destination_hash" ~ '^[0-9a-f]{64}$' AND "code_hash" ~ '^[0-9a-f]{64}$'),
    CONSTRAINT "otp_challenges_attempts_chk" CHECK ("max_attempts" BETWEEN 1 AND 20 AND "attempts" BETWEEN 0 AND "max_attempts"),
    CONSTRAINT "otp_challenges_expiry_chk" CHECK ("expires_at" > "created_at")
);

